const storageKeys={leads:'nexum_admin_leads',pricing:'nexum_admin_pricing',content:'nexum_admin_content'};
const seedLeads=[
  {id:crypto.randomUUID(),name:'Ayesha Malik',company:'BrightPath Consulting',email:'ayesha@example.com',plan:'Growth',message:'Lead qualification and consultation booking.',status:'New',createdAt:Date.now()-1000*60*42},
  {id:crypto.randomUUID(),name:'Hamza Tariq',company:'Northline Retail',email:'hamza@example.com',plan:'Custom',message:'Product support across several categories.',status:'Qualified',createdAt:Date.now()-1000*60*60*8},
  {id:crypto.randomUUID(),name:'Sara Ahmed',company:'Studio Arc',email:'sara@example.com',plan:'Starter',message:'A focused FAQ assistant for service pages.',status:'Contacted',createdAt:Date.now()-1000*60*60*27},
  {id:crypto.randomUUID(),name:'Bilal Khan',company:'Vertex Systems',email:'bilal@example.com',plan:'Growth',message:'Website lead capture and CRM handoff.',status:'Won',createdAt:Date.now()-1000*60*60*50},
  {id:crypto.randomUUID(),name:'Mina Raza',company:'Aura Wellness',email:'mina@example.com',plan:'Not sure',message:'Help visitors choose and book a service.',status:'New',createdAt:Date.now()-1000*60*60*74}
];
const defaultPricing=[{name:'Starter',price:'150,000',description:'Focused chatbot for essential questions and a clear customer journey.'},{name:'Growth',price:'300,000',description:'Multiple flows, lead qualification, and selected workflow connections.'},{name:'Custom',price:'600,000+',description:'Complex journeys, larger knowledge sets, and advanced integrations.'}];
const defaultContent={heroTitle:'Every conversation. Connected.',heroLead:'An AI chatbot built around your business—ready to answer, guide, qualify, and support your customers around the clock.',ctaTitle:'Find the right chatbot package.',contactEmail:'info@nexumglobal.solutions'};
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
const write=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
let leads=read(storageKeys.leads,seedLeads);if(!localStorage.getItem(storageKeys.leads))write(storageKeys.leads,leads);
let pricing=read(storageKeys.pricing,defaultPricing);let content=read(storageKeys.content,defaultContent);

const $=(selector,root=document)=>root.querySelector(selector);const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const formatAge=time=>{const mins=Math.floor((Date.now()-time)/60000);if(mins<60)return `${mins}m ago`;const hours=Math.floor(mins/60);if(hours<24)return `${hours}h ago`;return `${Math.floor(hours/24)}d ago`};
const initials=name=>name.split(' ').map(part=>part[0]).join('').slice(0,2).toUpperCase();

function switchView(name){$$('[data-view-panel]').forEach(panel=>{const active=panel.dataset.viewPanel===name;panel.hidden=!active;panel.classList.toggle('active',active)});$$('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===name));$('[data-view-title]').textContent=name.charAt(0).toUpperCase()+name.slice(1);$('#sidebar').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');if(name==='leads')renderLeadTable()}
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.view)));$('[data-open-leads]').addEventListener('click',()=>switchView('leads'));
$('.menu-toggle').addEventListener('click',event=>{const open=$('#sidebar').classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',String(open))});

function renderMetrics(){const count=status=>leads.filter(lead=>lead.status===status).length;$('[data-metric-total]').textContent=leads.length;$('[data-metric-followup]').textContent=leads.filter(lead=>['New','Contacted'].includes(lead.status)).length;$('[data-metric-qualified]').textContent=count('Qualified');$('[data-metric-won]').textContent=count('Won');$$('[data-lead-count]').forEach(el=>el.textContent=leads.length)}
function renderChart(){const values=[2,4,3,6,5,8,Math.max(3,leads.filter(lead=>Date.now()-lead.createdAt<86400000).length+3)],days=['Thu','Fri','Sat','Sun','Mon','Tue','Wed'];const max=Math.max(...values);$('[data-chart]').innerHTML=values.map((value,index)=>`<div class="bar-column"><i style="height:${value/max*88}%"></i><small>${days[index]}</small></div>`).join('')}
function renderPlanMix(){const total=Math.max(1,leads.length);const plans=['Starter','Growth','Custom','Not sure'];$('[data-plan-mix]').innerHTML=plans.map(plan=>{const count=leads.filter(lead=>lead.plan===plan).length;const percent=Math.round(count/total*100);return `<div class="mix-row"><span>${plan}</span><div class="mix-track"><i style="width:${percent}%"></i></div><b>${percent}%</b></div>`}).join('')}
function leadMarkup(lead){return `<div class="compact-lead"><div class="lead-person"><span class="lead-avatar">${initials(lead.name)}</span><div><b>${lead.name}</b><small>${lead.company} · ${formatAge(lead.createdAt)}</small></div></div><span class="plan-pill">${lead.plan}</span><span class="status-pill" data-status="${lead.status}">${lead.status}</span></div>`}
function renderRecent(){$('[data-recent-leads]').innerHTML=[...leads].sort((a,b)=>b.createdAt-a.createdAt).slice(0,4).map(leadMarkup).join('')}
function renderDashboard(){renderMetrics();renderChart();renderPlanMix();renderRecent()}

function renderLeadTable(){const search=$('[data-search]').value.toLowerCase();const status=$('[data-status-filter]').value;const plan=$('[data-plan-filter]').value;const filtered=[...leads].sort((a,b)=>b.createdAt-a.createdAt).filter(lead=>(status==='all'||lead.status===status)&&(plan==='all'||lead.plan===plan)&&`${lead.name} ${lead.company} ${lead.email}`.toLowerCase().includes(search));$('[data-lead-table]').innerHTML=filtered.map(lead=>`<tr><td><div class="lead-person"><span class="lead-avatar">${initials(lead.name)}</span><div><b>${lead.name}</b><small>${lead.company}<br>${lead.email}</small></div></div></td><td><span class="plan-pill">${lead.plan}</span></td><td>${formatAge(lead.createdAt)}</td><td><select data-status-id="${lead.id}">${['New','Contacted','Qualified','Won','Archived'].map(value=>`<option ${value===lead.status?'selected':''}>${value}</option>`).join('')}</select></td><td><button class="row-action" data-archive="${lead.id}">Archive</button></td></tr>`).join('');$('[data-empty]').hidden=filtered.length>0;$$('[data-status-id]').forEach(select=>select.addEventListener('change',()=>{const lead=leads.find(item=>item.id===select.dataset.statusId);lead.status=select.value;persistLeads()}));$$('[data-archive]').forEach(button=>button.addEventListener('click',()=>{const lead=leads.find(item=>item.id===button.dataset.archive);lead.status='Archived';persistLeads()}))}
function persistLeads(){write(storageKeys.leads,leads);renderDashboard();renderLeadTable()}
['[data-search]','[data-status-filter]','[data-plan-filter]'].forEach(selector=>$(selector).addEventListener(selector==='[data-search]'?'input':'change',renderLeadTable));

const leadDialog=$('[data-lead-dialog]');$$('[data-add-lead]').forEach(button=>button.addEventListener('click',()=>leadDialog.showModal()));$('[data-lead-form]').addEventListener('submit',event=>{if(event.submitter?.value==='cancel')return;event.preventDefault();const data=new FormData(event.currentTarget);leads.unshift({id:crypto.randomUUID(),name:data.get('name'),company:data.get('company'),email:data.get('email'),plan:data.get('plan'),message:data.get('message'),status:'New',createdAt:Date.now()});event.currentTarget.reset();leadDialog.close();persistLeads()});
$('[data-export]').addEventListener('click',()=>{const quote=value=>`"${String(value).replaceAll('"','""')}"`;const rows=[['Name','Company','Email','Plan','Status','Message','Created'],...leads.map(lead=>[lead.name,lead.company,lead.email,lead.plan,lead.status,lead.message,new Date(lead.createdAt).toISOString()])];const blob=new Blob([rows.map(row=>row.map(quote).join(',')).join('\n')],{type:'text/csv'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='nexum-leads.csv';link.click();URL.revokeObjectURL(link.href)});

function renderPricing(){$('[data-pricing-editor]').innerHTML=pricing.map((plan,index)=>`<article class="price-edit-card"><h3>${plan.name}</h3><label>Starting price (PKR)<input data-price-index="${index}" data-field="price" value="${plan.price}"></label><label>Description<textarea data-price-index="${index}" data-field="description">${plan.description}</textarea></label></article>`).join('')}
$('[data-save-pricing]').addEventListener('click',()=>{$$('[data-price-index]').forEach(input=>pricing[Number(input.dataset.priceIndex)][input.dataset.field]=input.value);write(storageKeys.pricing,pricing);$('[data-pricing-status]').textContent='Pricing draft saved in this browser.';setTimeout(()=>$('[data-pricing-status]').textContent='',2500)});
$$('[data-content]').forEach(input=>input.value=content[input.dataset.content]);$('[data-save-content]').addEventListener('click',()=>{$$('[data-content]').forEach(input=>content[input.dataset.content]=input.value);write(storageKeys.content,content);$('[data-content-status]').textContent='Content draft saved in this browser.';setTimeout(()=>$('[data-content-status]').textContent='',2500)});

renderPricing();renderDashboard();renderLeadTable();
